    """Trace 2-lines through the gaps in horizontal 8-bars."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = next(((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if marker is None:
        return out
    bars = [r for r, row in enumerate(grid) if sum(v == 8 for v in row) >= w // 2]
    if not bars:
        return out
    holes = {r: [c for c, v in enumerate(grid[r]) if v == 0] for r in bars}
    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
            out[r][c] = 2
    # Gates through each bar.
    for r in bars:
        for c in holes[r]:
            paint(r, c)
    # Connect the marker to the first bar through the row immediately above it.
    r0, c0 = marker
    first = bars[0]
    if r0 < first and first - r0 > 0 and holes[first]:
        rr = first - 1
        lo, hi = min([c0] + holes[first]), max([c0] + holes[first])
        for c in range(lo, hi + 1):
            paint(rr, c)
    # Connect successive horizontal bars. A one-row gap spans the next gates;
    # a two-row gap carries the old gates down before joining across the row.
    for a, b in zip(bars, bars[1:]):
        gap = b - a
        prev, nxt = holes[a], holes[b]
        if gap == 2:
            if nxt:
                for c in range(min(nxt), max(nxt) + 1):
                    paint(a + 1, c)
        elif gap >= 3:
            for c in prev:
                for rr in range(a + 1, b - 1):
                    paint(rr, c)
            for c in range(w):
                paint(b - 1, c)
    # Continue the final gates to the lower edge.
    last = bars[-1]
    for c in holes[last]:
        for r in range(last + 1, h):
            paint(r, c)
    return out
'''
